package com.example.payment.integrationtest.paymentgateway;

import static com.github.tomakehurst.wiremock.client.WireMock.aResponse;
import static com.github.tomakehurst.wiremock.client.WireMock.equalToJson;
import static com.github.tomakehurst.wiremock.client.WireMock.post;
import static com.github.tomakehurst.wiremock.client.WireMock.postRequestedFor;
import static com.github.tomakehurst.wiremock.client.WireMock.urlEqualTo;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.github.tomakehurst.wiremock.junit5.WireMockRuntimeInfo;
import com.github.tomakehurst.wiremock.junit5.WireMockTest;
import java.math.BigDecimal;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

@WireMockTest
class HttpPaymentGatewayTest {

    private static final String PATH = "/v1/authorizations";

    private HttpPaymentGateway gateway;
    private WireMockRuntimeInfo provider;

    @BeforeEach
    void setUp(WireMockRuntimeInfo provider) {
        this.provider = provider;
        gateway = new HttpPaymentGateway(RestClient.builder().baseUrl(provider.getHttpBaseUrl()).build());
    }

    private void providerAnswers(int status, String body) {
        provider.getWireMock().register(post(urlEqualTo(PATH)).willReturn(
                aResponse().withStatus(status).withHeader("Content-Type", "application/json").withBody(body)));
    }

    @Test
    void the_authorization_is_sent_as_json_with_reference_amount_and_currency() {
        providerAnswers(200, "{\"status\":\"approved\"}");

        gateway.authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));

        provider.getWireMock().verifyThat(1, postRequestedFor(urlEqualTo(PATH))
                .withHeader("Content-Type", com.github.tomakehurst.wiremock.client.WireMock.containing("application/json"))
                .withRequestBody(equalToJson("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}", false, false)));
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        providerAnswers(200, "{\"status\":\"approved\"}");

        assertThat(gateway.authorize("ORD-1", new Money(BigDecimal.TEN, "EUR")))
                .isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        providerAnswers(200, "{\"status\":\"declined\"}");

        assertThat(gateway.authorize("ORD-2", new Money(BigDecimal.TEN, "EUR")))
                .isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void unknown_fields_in_the_answer_are_ignored() {
        providerAnswers(200, "{\"status\":\"approved\",\"id\":\"auth_1\",\"extra\":{\"a\":1}}");

        assertThat(gateway.authorize("ORD-3", new Money(BigDecimal.TEN, "EUR")))
                .isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_refusal_with_402_is_a_declined_outcome() {
        providerAnswers(402, "{\"error\":\"card_refused\"}");

        assertThat(gateway.authorize("ORD-4", new Money(BigDecimal.TEN, "EUR")))
                .isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_rejected_request_is_reported_as_a_failure_not_a_decline() {
        providerAnswers(400, "{\"error\":\"invalid_currency\"}");

        assertThatThrownBy(() -> gateway.authorize("ORD-5", new Money(BigDecimal.TEN, "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_is_reported_as_a_failure_not_a_decline() {
        providerAnswers(503, "");

        assertThatThrownBy(() -> gateway.authorize("ORD-6", new Money(BigDecimal.TEN, "EUR")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }
}
